#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-24
//
// artifact.mjs: the one writer of ork task artifacts (plan, research). Ported
// from the humanlayer riptide create/iterate pattern (Apache-2.0), with the
// review comments kept INSIDE the artifact file instead of a cloud service, so
// a reviewer comments on the file and the next iterate keeps every comment.
//
// Canonical copy: scripts/_shared/artifact.mjs. scripts/sync-shared-scripts.sh
// copies it into each consumer skill's scripts/ (the plugin build ships skills
// one folder each). The layout is a contract: create-plan's
// references/artifact-layout.md documents it, and L2's auto-advance reads it.
//
// Exit codes: 0 done, 1 refused by artifact state (approve with open
// comments), 2 bad usage or invalid input (nothing written).

import { readFile, writeFile, mkdir, readdir, rename } from 'node:fs/promises';
import { realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { join, resolve } from 'node:path';

const run = promisify(execFile);
export const KINDS = ['research', 'plan'];
export const SCHEMA = 1;
const OPEN_MARK = '<!-- ork:comments -->';
const CLOSE_MARK = '<!-- /ork:comments -->';
const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const FILE_RE = /^(\d{2})-.+\.md$/;

class UsageError extends Error {}

// The only options that take no value. Every other option needs one: a string
// option left empty used to become `true` (a "true" title, a TypeError exit 3).
const FLAGS = new Set(['open', 'json']);

function args(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith('--')) { out._.push(a); continue; }
    const key = a.slice(2);
    if (FLAGS.has(key)) { out[key] = true; continue; }
    const next = argv[i + 1];
    if (next === undefined || next.startsWith('--')) throw new UsageError(`--${key} needs a value`);
    out[key] = next; i++;
  }
  return out;
}

function need(o, key) {
  if (typeof o[key] !== 'string' || o[key] === '') throw new UsageError(`--${key} is required`);
  return o[key];
}

async function git(...a) {
  try { return (await run('git', a, { encoding: 'utf8' })).stdout.trim(); } catch { return ''; }
}

// The origin remote names the repository; the top-level folder does not in a
// worktree (.worktrees/<task> would be recorded as the repo).
async function repoName() {
  const url = await git('remote', 'get-url', 'origin');
  const fromUrl = url.replace(/\.git$/, '').split(/[/:]/).pop();
  return fromUrl || (await git('rev-parse', '--show-toplevel')).split('/').pop() || '';
}

async function defaultTasksDir() {
  const top = await git('rev-parse', '--show-toplevel');
  return join(top || process.cwd(), '.ork', 'tasks');
}

function oneLine(s, what) {
  const v = String(s).replace(/\s*\n\s*/g, ' ').trim();
  // <comment too: comments() would read it as a second, unreadable opening.
  const low = v.toLowerCase(); // any letter case: comments() reads them all
  if (low.includes('</comment>') || v.includes('<!--') || low.includes('<comment')) {
    throw new UsageError(`${what} must not contain <comment, </comment> or <!--`);
  }
  return v;
}

// An attribute value must read back through comments(): no quote, and no < or >,
// which also keep the editComment() tag match and the reply line unambiguous.
function attr(s) {
  const v = oneLine(s, 'attribute').replace(/"/g, "'");
  if (/[<>]/.test(v)) throw new UsageError('names and references must not contain < or >');
  return v;
}

// ---- parse and write ------------------------------------------------------

export function parse(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n/);
  if (!m) throw new UsageError('not an ork artifact: no front matter');
  const fm = {};
  for (const line of m[1].split(/\r?\n/)) {
    const i = line.indexOf(': ');
    if (i > 0) fm[line.slice(0, i)] = line.slice(i + 2);
  }
  if (fm.ork_artifact !== String(SCHEMA)) throw new UsageError('not an ork artifact: ork_artifact is not 1');
  const rest = text.slice(m[0].length);
  const a = rest.lastIndexOf(OPEN_MARK);
  const b = rest.lastIndexOf(CLOSE_MARK);
  if (a < 0 || b < a) throw new UsageError('artifact has no comment block');
  return { fm, fmRaw: m[1], body: rest.slice(0, a), block: rest.slice(a, b + CLOSE_MARK.length), tail: rest.slice(b + CLOSE_MARK.length) };
}

function fmText(fm) {
  return Object.entries(fm).map(([k, v]) => `${k}: ${v}`).join('\n');
}

function assemble(fm, body, block, tail = '\n') {
  const b = body.endsWith('\n') ? body : `${body}\n`;
  return `---\n${fmText(fm)}\n---\n${b}\n${block}${tail}`;
}

// Atomic write: a crash mid-write must not leave half an artifact for L2 to read.
async function save(path, text) {
  const tmp = `${path}.tmp-${process.pid}`;
  await writeFile(tmp, text);
  await rename(tmp, path);
}

// Every `<comment` opening in the block yields an entry. One the parser cannot
// read (no closing tag, an open tag with an unquoted or unknown shape) comes back
// as an open comment marked `unreadable`, so approve refuses and status reports
// done=false: a comment is never silently skipped (review HOLD on #4897).
// CRLF and a comment on one line are read like the documented shape.
const OPEN_TAG = /<comment((?:\s+[a-z_]+="[^"]*")*)\s*>/y;

export function comments(block) {
  const src = block.replace(/\r\n?/g, '\n');
  const out = [];
  // Case-insensitive on purpose: a <Comment> or <COMMENT> tag must not be
  // skipped. OPEN_TAG stays lowercase, so any other spelling comes back
  // unreadable and blocks approve (review HOLD 6411209651).
  const opening = /<comment\b/gi;
  const nextOpening = /<comment\b/gi;
  let m;
  while ((m = opening.exec(src))) {
    OPEN_TAG.lastIndex = m.index;
    const h = OPEN_TAG.exec(src);
    const end = h ? src.indexOf('</comment>', OPEN_TAG.lastIndex) : -1;
    nextOpening.lastIndex = h ? OPEN_TAG.lastIndex : 0;
    const nm = h ? nextOpening.exec(src) : null;
    const next = nm ? nm.index : -1;
    if (!h || end < 0 || (next >= 0 && next < end)) {
      const line = src.slice(0, m.index).split('\n').length;
      out.push({ id: null, author: '', status: 'open', unreadable: true, quote: '',
        text: `unreadable comment at block line ${line}: ${src.slice(m.index).split('\n')[0]}`, replies: [] });
      continue;
    }
    const at = {};
    for (const [, k, v] of h[1].matchAll(/([a-z_]+)="([^"]*)"/g)) at[k] = v;
    const c = { id: at.id, author: at.author || '', status: at.status || 'open', quote: '', text: '', replies: [] };
    const text = [];
    for (const line of src.slice(OPEN_TAG.lastIndex, end).split('\n')) {
      if (line.startsWith('> ')) c.quote = c.quote ? `${c.quote}\n${line.slice(2)}` : line.slice(2);
      else if (/^ {2}\S[^:]*: /.test(line)) {
        const j = line.indexOf(': ');
        c.replies.push({ author: line.slice(2, j), text: line.slice(j + 2) });
      } else if (line.trim()) text.push(line);
    }
    c.text = text.join('\n');
    out.push(c);
    opening.lastIndex = end + '</comment>'.length;
  }
  return out;
}

function bodyOf(raw) {
  if (raw.includes(OPEN_MARK) || raw.includes(CLOSE_MARK)) {
    throw new UsageError('the body must not carry its own comment block; comments live in the artifact and are kept by iterate');
  }
  return raw;
}

// ---- commands -------------------------------------------------------------

async function cmdCreate(o) {
  const task = need(o, 'task');
  const kind = need(o, 'kind');
  const slug = need(o, 'slug');
  if (!KINDS.includes(kind)) throw new UsageError(`--kind must be one of ${KINDS.join(', ')}`);
  if (!SLUG_RE.test(slug) || !SLUG_RE.test(task)) throw new UsageError('--task and --slug must be kebab-case (a-z, 0-9, -)');
  const body = bodyOf(await readFile(need(o, 'body'), 'utf8'));
  const dir = join(resolve(o['tasks-dir'] || (await defaultTasksDir())), task);
  await mkdir(dir, { recursive: true });
  const nn = (await readdir(dir)).map((f) => FILE_RE.exec(f)).filter(Boolean).map((m) => Number(m[1]));
  const next = String((nn.length ? Math.max(...nn) : 0) + 1).padStart(2, '0');
  const path = join(dir, `${next}-${kind}-${slug}.md`);
  const now = new Date().toISOString();
  const fm = {
    ork_artifact: String(SCHEMA),
    task,
    kind,
    slug,
    title: JSON.stringify(oneLine(o.title || slug, 'title')),
    author: attr(need(o, 'author')), // a real seat name, so the non-author approval check means something
    revision: '1',
    status: 'draft',
    created: now,
    updated: now,
    repo: await repoName(),
    branch: await git('branch', '--show-current'),
    sha: await git('rev-parse', 'HEAD'),
  };
  await save(path, assemble(fm, body, `${OPEN_MARK}\n${CLOSE_MARK}`));
  console.log(path);
}

async function load(o) {
  const path = need(o, 'file');
  return { path, a: parse(await readFile(path, 'utf8')) };
}

async function cmdIterate(o) {
  const { path, a } = await load(o);
  const body = bodyOf(await readFile(need(o, 'body'), 'utf8'));
  a.fm.revision = String(Number(a.fm.revision || '1') + 1);
  a.fm.updated = new Date().toISOString();
  if (a.fm.status === 'approved') {
    a.fm.status = 'in-review'; // a changed artifact needs a new approval
    delete a.fm.approved_by; delete a.fm.approved_at; delete a.fm.approved_ref;
  }
  a.fm.sha = (await git('rev-parse', 'HEAD')) || a.fm.sha;
  // The comment block is written back exactly as read: iterate never drops,
  // reorders or rewrites a review comment. Resolving is review-artifact-comments' job.
  await save(path, assemble(a.fm, body, a.block, a.tail));
  console.log(`${path} revision ${a.fm.revision}`);
}

async function cmdComment(o) {
  const { path, a } = await load(o);
  const ids = comments(a.block).map((c) => Number(String(c.id).replace(/^c/, ''))).filter(Number.isFinite);
  const id = `c${(ids.length ? Math.max(...ids) : 0) + 1}`;
  const lines = [`<comment id="${id}" author="${attr(need(o, 'author'))}" status="open" at="${new Date().toISOString()}">`];
  if (typeof o.quote === 'string') lines.push(`> ${oneLine(o.quote, 'quote')}`);
  lines.push(oneLine(need(o, 'text'), 'text'), '</comment>');
  // A function, not a string: a replacement string would expand $$, $& and $` in the text.
  const block = a.block.replace(CLOSE_MARK, () => `${lines.join('\n')}\n${CLOSE_MARK}`);
  if (a.fm.status === 'draft') a.fm.status = 'in-review';
  await save(path, assemble(a.fm, a.body, block, a.tail));
  console.log(id);
}

function editComment(block, id, fn) {
  const re = new RegExp(`(<comment id="${id.replace(/[^a-z0-9]/gi, '')}"(?:\\s+[a-z_]+="[^"]*")*\\s*>)([\\s\\S]*?)(\\r?\\n?</comment>)`);
  if (!re.test(block)) throw new UsageError(`no comment ${id}`);
  return block.replace(re, (_, open, inner, close) => fn(open, inner, close));
}

async function cmdReply(o, resolveIt) {
  const { path, a } = await load(o);
  const id = need(o, 'id');
  const line = `  ${attr(need(o, 'author'))}: ${oneLine(need(o, 'text'), 'text')}`;
  const block = editComment(a.block, id, (open, inner, close) => {
    const head = resolveIt ? open.replace(/status="[^"]*"/, 'status="resolved"') : open;
    return `${head}${inner}\n${line}${close}`;
  });
  await save(path, assemble(a.fm, a.body, block, a.tail));
}

async function cmdList(o) {
  const { a } = await load(o);
  let list = comments(a.block);
  if (o.open) list = list.filter((c) => c.status !== 'resolved');
  if (o.json) console.log(JSON.stringify(list));
  else for (const c of list) console.log(`${c.id ?? '?'} [${c.status}] ${c.author}: ${c.text}${c.quote ? `  (on: ${c.quote})` : ''}`);
}

// An approval must come from a reviewer, never from the seat that wrote the
// artifact: L2 reads approved as "phase done" and must not advance on a lane
// approving itself (review comment c1 on the L6 plan).
const sameSeat = (x, y) => String(x).trim().toLowerCase() === String(y).trim().toLowerCase();

async function cmdApprove(o) {
  const by = attr(need(o, 'by'));
  const ref = attr(need(o, 'ref'));
  const { path, a } = await load(o);
  const open = comments(a.block).filter((c) => c.status !== 'resolved');
  if (open.length) {
    console.error(`refused: ${open.length} open comment(s): ${open.map((c) => c.id ?? 'unreadable').join(', ')}`);
    for (const c of open.filter((x) => x.unreadable)) console.error(`  ${c.text}; fix its shape to the documented one`);
    process.exitCode = 1;
    return;
  }
  if (a.fm.author && sameSeat(by, a.fm.author)) {
    console.error(`refused: ${by} is the author of this artifact; a reviewer must approve it`);
    process.exitCode = 1;
    return;
  }
  const now = new Date().toISOString();
  a.fm.status = 'approved';
  a.fm.updated = now;
  a.fm.approved_by = by;
  a.fm.approved_at = now;
  a.fm.approved_ref = ref;
  await save(path, assemble(a.fm, a.body, a.block, a.tail));
  console.log(`${path} approved`);
}

export async function status(dir) {
  const out = [];
  for (const f of (await readdir(dir)).sort()) {
    if (!FILE_RE.test(f)) continue;
    let a;
    // An artifact that no longer parses is reported, never dropped: L2 must not
    // read its absence as "nothing left to do".
    try { a = parse(await readFile(join(dir, f), 'utf8')); } catch (e) {
      out.push({ file: f, kind: null, slug: null, revision: null, status: 'unreadable', open_comments: null,
        approved_by: null, done: false, error: e.message });
      continue;
    }
    const open = comments(a.block).filter((c) => c.status !== 'resolved').length;
    out.push({
      file: f, kind: a.fm.kind, slug: a.fm.slug, revision: Number(a.fm.revision),
      status: a.fm.status, open_comments: open, approved_by: a.fm.approved_by || null,
      done: a.fm.status === 'approved' && open === 0 && Boolean(a.fm.approved_by)
        && !(a.fm.author && sameSeat(a.fm.approved_by, a.fm.author)),
    });
  }
  return out;
}

async function cmdStatus(o) {
  const s = await status(resolve(need(o, 'task-dir')));
  if (o.json) console.log(JSON.stringify(s));
  else for (const r of s) console.log(`${r.file}  ${r.kind} r${r.revision} ${r.status} open=${r.open_comments}${r.done ? '  DONE' : ''}`);
}

const USAGE = `usage: artifact.mjs <command> [options]
  create   --task T --kind ${KINDS.join('|')} --slug S --body FILE --author SEAT [--title X] [--tasks-dir D]
  iterate  --file F --body FILE
  comment  --file F --author A --text X [--quote LINE]
  reply    --file F --id cN --author A --text X
  resolve  --file F --id cN --author A --text X
  list     --file F [--open] [--json]
  approve  --file F --by REVIEWER_SEAT --ref LAND_OR_COMMENT_ID
  status   --task-dir D [--json]`;

const COMMANDS = {
  create: cmdCreate, iterate: cmdIterate, comment: cmdComment,
  reply: (o) => cmdReply(o, false), resolve: (o) => cmdReply(o, true),
  list: cmdList, approve: cmdApprove, status: cmdStatus,
};

// Compare real paths on both sides: node reports import.meta.url as the real
// path, so a symlinked argv path would never match and every command would exit 0.
const real = (p) => { try { return realpathSync(p); } catch { return resolve(p); } };
const isMain = Boolean(process.argv[1]) && real(process.argv[1]) === real(fileURLToPath(import.meta.url));
if (isMain) {
  const [cmd, ...rest] = process.argv.slice(2);
  const fn = COMMANDS[cmd];
  if (!fn) { console.error(USAGE); process.exit(2); }
  // args() runs inside the chain so its UsageError exits 2 like every other.
  Promise.resolve().then(() => fn(args(rest))).catch((e) => {
    console.error(e instanceof UsageError ? `error: ${e.message}` : e.stack || String(e));
    process.exit(e instanceof UsageError ? 2 : 3);
  });
}
